import type { ButtonHTMLAttributes, ComponentType, InputHTMLAttributes, ReactNode } from "react";

// Class name overrides
// Every component exposes a classNames prop keyed by sub-element name.
// Pass a string to append classes, or a function that receives defaults.

export type ClassNameOverride = string | ((defaultClassName: string) => string);

// Slot replacement
// Every component exposes a components prop for full slot replacement.

export interface InputSlotProps extends InputHTMLAttributes<HTMLInputElement> {
	label: string;
	error?: string;
}

export interface ButtonSlotProps extends ButtonHTMLAttributes<HTMLButtonElement> {
	loading?: boolean;
	children: ReactNode;
}

export interface LinkSlotProps {
	href: string;
	children: ReactNode;
	className?: string;
	onClick?: () => void;
}

export interface DividerSlotProps {
	label?: string;
	className?: string;
}

export interface ErrorSlotProps {
	message: string;
	className?: string;
}

export interface AvatarSlotProps {
	src?: string;
	name?: string;
	className?: string;
}

// Shared component slots

export interface SharedSlots {
	Input?: ComponentType<InputSlotProps>;
	Button?: ComponentType<ButtonSlotProps>;
	Link?: ComponentType<LinkSlotProps>;
	Divider?: ComponentType<DividerSlotProps>;
	Error?: ComponentType<ErrorSlotProps>;
}

// OAuth provider metadata

export interface OAuthProviderMeta {
	id: string;
	name: string;
	icon?: ReactNode;
	color?: string;
}

// Sign-in component

export interface SignInClassNames {
	root?: ClassNameOverride;
	card?: ClassNameOverride;
	title?: ClassNameOverride;
	form?: ClassNameOverride;
	input?: ClassNameOverride;
	label?: ClassNameOverride;
	button?: ClassNameOverride;
	error?: ClassNameOverride;
	footer?: ClassNameOverride;
	divider?: ClassNameOverride;
	oauthSection?: ClassNameOverride;
	link?: ClassNameOverride;
}

/**
 * What `SignIn` needs from a passkey client. `createPasskeyClient` from
 * `@glinr/theauth-client` satisfies it.
 */
export interface PasskeyClientLike {
	isSupported(): boolean;
	isConditionalAvailable(): Promise<boolean>;
	signIn(options?: {
		conditional?: boolean;
		signal?: AbortSignal;
	}): Promise<{ ok: true } | { ok: false; reason: string; message: string }>;
}

export interface SignInProps {
	classNames?: SignInClassNames;
	/**
	 * Enables passkey sign-in: a button, and autofill suggestions in the email
	 * field when the browser supports conditional UI.
	 */
	passkeyClient?: PasskeyClientLike;
	/** Offer saved passkeys in the email field's autofill. Default true. */
	passkeyAutofill?: boolean;
	components?: SharedSlots;
	providers?: OAuthProviderMeta[];
	basePath?: string;
	onSuccess?: () => void;
	forgotPasswordUrl?: string;
	onForgotPassword?: () => void;
	signUpUrl?: string;
	onSignUp?: () => void;
	showMagicLink?: boolean;
	title?: string;
	footer?: ReactNode;
	disabled?: boolean;
	className?: string;
}

// Sign-up component

export interface SignUpClassNames {
	root?: ClassNameOverride;
	card?: ClassNameOverride;
	title?: ClassNameOverride;
	form?: ClassNameOverride;
	input?: ClassNameOverride;
	label?: ClassNameOverride;
	button?: ClassNameOverride;
	error?: ClassNameOverride;
	footer?: ClassNameOverride;
	divider?: ClassNameOverride;
	oauthSection?: ClassNameOverride;
	link?: ClassNameOverride;
}

export interface SignUpProps {
	classNames?: SignUpClassNames;
	components?: SharedSlots;
	providers?: OAuthProviderMeta[];
	basePath?: string;
	onSuccess?: () => void;
	signInUrl?: string;
	onSignIn?: () => void;
	showName?: boolean;
	confirmPassword?: boolean;
	title?: string;
	footer?: ReactNode;
	disabled?: boolean;
	className?: string;
}

// User button

export interface UserButtonClassNames {
	root?: ClassNameOverride;
	trigger?: ClassNameOverride;
	avatar?: ClassNameOverride;
	dropdown?: ClassNameOverride;
	menuItem?: ClassNameOverride;
	name?: ClassNameOverride;
	email?: ClassNameOverride;
}

export interface UserButtonMenuItem {
	label: string;
	onClick: () => void;
	icon?: ReactNode;
	danger?: boolean;
}

export interface UserButtonProps {
	classNames?: UserButtonClassNames;
	components?: SharedSlots & {
		Avatar?: ComponentType<AvatarSlotProps>;
	};
	menuItems?: UserButtonMenuItem[];
	onSignOut?: () => void;
	showEmail?: boolean;
	className?: string;
}

// OAuth buttons

export interface OAuthButtonsClassNames {
	root?: ClassNameOverride;
	button?: ClassNameOverride;
	icon?: ClassNameOverride;
	label?: ClassNameOverride;
}

export interface OAuthButtonsProps {
	classNames?: OAuthButtonsClassNames;
	components?: {
		Button?: ComponentType<ButtonSlotProps>;
	};
	providers: OAuthProviderMeta[];
	basePath?: string;
	mode?: "signin" | "signup";
	layout?: "grid" | "list";
	disabled?: boolean;
	className?: string;
}

// Forgot password

export interface ForgotPasswordClassNames {
	root?: ClassNameOverride;
	card?: ClassNameOverride;
	title?: ClassNameOverride;
	form?: ClassNameOverride;
	input?: ClassNameOverride;
	button?: ClassNameOverride;
	error?: ClassNameOverride;
	success?: ClassNameOverride;
	link?: ClassNameOverride;
}

export interface ForgotPasswordProps {
	classNames?: ForgotPasswordClassNames;
	components?: SharedSlots;
	basePath?: string;
	onSuccess?: () => void;
	signInUrl?: string;
	onSignIn?: () => void;
	title?: string;
	className?: string;
}

// Two-factor verify

export interface TwoFactorClassNames {
	root?: ClassNameOverride;
	card?: ClassNameOverride;
	title?: ClassNameOverride;
	description?: ClassNameOverride;
	form?: ClassNameOverride;
	input?: ClassNameOverride;
	button?: ClassNameOverride;
	error?: ClassNameOverride;
	backupLink?: ClassNameOverride;
}

export interface TwoFactorVerifyProps {
	classNames?: TwoFactorClassNames;
	components?: SharedSlots;
	basePath?: string;
	onSuccess?: () => void;
	onCancel?: () => void;
	digits?: number;
	showBackupOption?: boolean;
	title?: string;
	className?: string;
}

// Auth card

export interface AuthCardClassNames {
	root?: ClassNameOverride;
	card?: ClassNameOverride;
	title?: ClassNameOverride;
	description?: ClassNameOverride;
}

export interface AuthCardProps {
	classNames?: AuthCardClassNames;
	title?: string;
	description?: string;
	children: ReactNode;
	className?: string;
}

import type { ClassNameOverride } from "./types";

/**
 * Merge a default class string with an optional override.
 *
 * - If override is undefined, returns defaults as-is.
 * - If override is a string, appends it to defaults.
 * - If override is a function, calls it with defaults and uses the return value.
 */
export function cx(defaults: string, override?: ClassNameOverride): string {
	if (override === undefined) return defaults;
	if (typeof override === "function") return override(defaults);
	return `${defaults} ${override}`;
}

import type { ReactNode } from "react";
import { useId } from "react";
import type {
	ButtonSlotProps,
	DividerSlotProps,
	ErrorSlotProps,
	InputSlotProps,
} from "./types";

/**
 * Default slot implementations shared by the auth components. Hosts replace
 * any of them through the `components` prop.
 */

export function Spinner(): ReactNode {
	return (
		<svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none" aria-hidden="true">
			<circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
			<path
				className="opacity-75"
				fill="currentColor"
				d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
			/>
		</svg>
	);
}

export function DefaultInput({ label, error, ...rest }: InputSlotProps): ReactNode {
	const errorId = useId();
	return (
		<label className="theauth-field flex flex-col gap-1.5">
			<span className="text-sm font-medium text-zinc-700 dark:text-zinc-300">{label}</span>
			<input
				aria-invalid={error ? true : undefined}
				aria-describedby={error ? errorId : undefined}
				{...rest}
				className={
					rest.className ??
					"theauth-input w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm text-zinc-900 outline-none transition-colors placeholder:text-zinc-400 focus:border-zinc-500 focus:ring-1 focus:ring-zinc-500 dark:border-zinc-600 dark:bg-zinc-800 dark:text-zinc-100 dark:placeholder:text-zinc-500 dark:focus:border-zinc-400 dark:focus:ring-zinc-400"
				}
			/>
			{error && (
				<p id={errorId} role="alert" className="text-xs text-red-500">
					{error}
				</p>
			)}
		</label>
	);
}

export function DefaultButton({ loading, children, ...rest }: ButtonSlotProps): ReactNode {
	return (
		<button
			{...rest}
			disabled={rest.disabled ?? loading}
			aria-busy={loading ? true : undefined}
			className={
				rest.className ??
				"theauth-btn w-full rounded-lg bg-zinc-900 px-4 py-2.5 text-sm font-medium text-white transition-colors hover:bg-zinc-800 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
			}
		>
			{loading ? (
				<span className="flex items-center justify-center gap-2">
					<Spinner />
					{children}
				</span>
			) : (
				children
			)}
		</button>
	);
}

export function DefaultDivider({ label, className }: DividerSlotProps): ReactNode {
	return (
		<div className={className ?? "theauth-divider flex items-center gap-3 py-1"}>
			<div className="h-px flex-1 bg-zinc-200 dark:bg-zinc-700" />
			{label && <span className="text-xs text-zinc-400">{label}</span>}
			<div className="h-px flex-1 bg-zinc-200 dark:bg-zinc-700" />
		</div>
	);
}

/** `role="alert"` makes assistive tech announce the message when it appears. */
export function DefaultError({ message, className }: ErrorSlotProps): ReactNode {
	return (
		<div
			role="alert"
			className={
				className ??
				"theauth-error rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-600 dark:border-red-800 dark:bg-red-900/20 dark:text-red-400"
			}
		>
			{message}
		</div>
	);
}

import type { ReactNode } from "react";
import { useId } from "react";
import type { AuthCardProps } from "./types";
import { cx } from "./utils";

export function AuthCard({
	classNames,
	title,
	description,
	children,
	className,
}: AuthCardProps): ReactNode {
	const titleId = useId();
	return (
		<div
			className={cx(
				"theauth-auth-card-root flex min-h-screen items-center justify-center p-4",
				classNames?.root ?? className,
			)}
		>
			<section
				aria-labelledby={title ? titleId : undefined}
				className={cx(
					"theauth-auth-card w-full max-w-sm rounded-xl border border-zinc-200 bg-white p-8 shadow-sm dark:border-zinc-800 dark:bg-zinc-900",
					classNames?.card,
				)}
			>
				{title && (
					<h2
						id={titleId}
						className={cx(
							"theauth-auth-card-title mb-1 text-center text-xl font-semibold text-zinc-900 dark:text-zinc-100",
							classNames?.title,
						)}
					>
						{title}
					</h2>
				)}
				{description && (
					<p
						className={cx(
							"theauth-auth-card-desc mb-6 text-center text-sm text-zinc-500 dark:text-zinc-400",
							classNames?.description,
						)}
					>
						{description}
					</p>
				)}
				{!description && title && <div className="mb-6" />}
				{children}
			</section>
		</div>
	);
}
